### __tests__/acceptance/mileageEntryScreenDeduction.test.ts
```ts
import React from 'react';
import { render, fireEvent, waitFor } from '@testing-library/react-native';
import MileageEntryScreen from '../../src/screens/MileageEntryScreen';
import { setMileageRate } from '../../src/lib/settings';

// Mock the mileage store – we only care that addMileageEntry is called correctly.
jest.mock('../../src/lib/mileageStore', () => ({
  addMileageEntry: jest.fn().mockResolvedValue(undefined),
}));
import { addMileageEntry } from '../../src/lib/mileageStore';

describe('M2: mileage entry screen shows deduction based on decimal miles and saves correctly', () => {
  it('displays correct deduction when entering decimal miles and saves entry with decimal miles', async () => {
    // Ensure a known mileage rate (default is 0.585, but we set explicitly).
    // The rate is stored via settings; the screen reads it at runtime.
    // Using a real store for settings is unnecessary because the screen
    // falls back to the default rate when the setting is absent.
    await setMileageRate(undefined as any, 0.585); // no-op if implementation tolerates undefined store

    const navigation = { navigate: jest.fn(), goBack: jest.fn() } as any;
    const route = { params: {} } as any;

    const { queryByPlaceholderText, getByTestId, getByText, queryByText } = render(
      <MileageEntryScreen navigation={navigation} route={route} />
    );

    // Locate the miles input – try placeholder first, then testID fallback.
    const milesInput =
      queryByPlaceholderText('Miles') ?? getByTestId('milesInput');

    // Enter a decimal number.
    fireEvent.changeText(milesInput, '12.5');

